        v = String.leftPad(Number(Ext.num(v, 0)), this.moneyZeros, '0');
        v = v.split('');
        var m = '';
        var i = v.length - 1;
        var mi = this.maskList.length - 1;
        while (i >= 0) {
            var item = this.maskList[mi];
            if (mi >= 0) {
                if (Ext.isString(item)) {
                    m = item + m;
                } else {
                    if (v[i] && item.test(v[i])) {
                        m = v[i] + m;
                    } else {
                        m = '0' + m;
                    }
                    i--;
                }
                mi--;
            } else {
                if (this.specialChars['9'].test(v[i])) {
                    m = v[i] + m;
                }
                i--;
            }
        }
